func TestVerify(t *testing.T) {
	at := time.Unix(1700000000, 0)
	body := []byte(`{"id":"evt_1"}`)
	sig := func(secret string) string { return sigOf(secret, "1700000000."+string(body)) }
	const minute = time.Minute
	cases := []struct {
		name      string
		payload   []byte
		header    string
		secrets   []string
		tolerance time.Duration
		now       time.Time
		want      error
	}{
		{"valid", body, "t=1700000000,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, nil},
		{"any order, spaces, unknown keys", body, " v0=zz , v1 = " + sig("whsec_a") + " , t = 1700000000 ", []string{"whsec_a"}, 0, at, nil},
		{"one of several secrets", body, "t=1700000000,v1=" + sig("whsec_a"), []string{"whsec_x", "whsec_a"}, 0, at, nil},
		{"previous secret as second v1", body, "t=1700000000,v1=" + sig("whsec_new") + ",v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, nil},
		{"tolerance edge, past", body, "t=1700000000,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at.Add(5 * minute), nil},
		{"tolerance edge, future", body, "t=1700000000,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at.Add(-5 * minute), nil},
		{"custom tolerance", body, "t=1700000000,v1=" + sig("whsec_a"), []string{"whsec_a"}, 10 * minute, at.Add(7 * minute), nil},

		{"empty header", body, "", []string{"whsec_a"}, 0, at, webhooks.ErrMalformedHeader},
		{"blank header", body, "  ", []string{"whsec_a"}, 0, at, webhooks.ErrMalformedHeader},
		{"pair without =", body, "t=1700000000,v1", []string{"whsec_a"}, 0, at, webhooks.ErrMalformedHeader},
		{"empty pair", body, "t=1700000000,,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, webhooks.ErrMalformedHeader},
		{"t not an integer", body, "t=yesterday,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, webhooks.ErrMalformedHeader},
		{"t not whole seconds", body, "t=1700000000.5,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, webhooks.ErrMalformedHeader},
		{"malformed beats missing t", body, "v1=" + sig("whsec_a") + ",oops", []string{"whsec_a"}, 0, at, webhooks.ErrMalformedHeader},
		{"no t", body, "v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, webhooks.ErrNoTimestamp},
		{"too old", body, "t=1700000000,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at.Add(5*minute + time.Second), webhooks.ErrTimestampTolerance},
		{"too far in the future", body, "t=1700000000,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at.Add(-5*minute - time.Second), webhooks.ErrTimestampTolerance},
		{"tolerance beats missing signature", body, "t=1700000000", []string{"whsec_a"}, 0, at.Add(time.Hour), webhooks.ErrTimestampTolerance},
		{"no v1", body, "t=1700000000,v0=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, webhooks.ErrNoSignature},
		{"wrong secret", body, "t=1700000000,v1=" + sig("whsec_b"), []string{"whsec_a"}, 0, at, webhooks.ErrSignatureMismatch},
		{"no secrets", body, "t=1700000000,v1=" + sig("whsec_a"), nil, 0, at, webhooks.ErrSignatureMismatch},
		{"other payload", []byte(`{"id":"evt_2"}`), "t=1700000000,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, webhooks.ErrSignatureMismatch},
		{"changed timestamp", body, "t=1700000001,v1=" + sig("whsec_a"), []string{"whsec_a"}, 0, at, webhooks.ErrSignatureMismatch},
	}
	for _, c := range cases {
		err := webhooks.Verify(c.payload, c.header, c.secrets, c.tolerance, c.now)
		if c.want == nil && err != nil {
			t.Errorf("%s: Verify = %v", c.name, err)
		}
		if c.want != nil && !errors.Is(err, c.want) {
			t.Errorf("%s: Verify = %v, want %v", c.name, err, c.want)
		}
	}
}

