func TestRotateSecretEndpoint(t *testing.T) {
	e := apitest.New(t)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	var rot store.WebhookEndpoint
	e.MustDo(http.StatusOK, "POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Acme.Key, nil, &rot)
	hexPart, _ := strings.CutPrefix(rot.Secret, "whsec_")
	if rot.ID != ep.ID || rot.Secret == ep.Secret || len(hexPart) != 32 {
		t.Fatalf("rotated endpoint = %+v (before: %+v)", rot, ep)
	}
	if _, err := hex.DecodeString(hexPart); err != nil {
		t.Fatalf("secret %q: %v", rot.Secret, err)
	}
	if r := e.Do("POST", "/v1/webhook-endpoints/nope/rotate-secret", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("unknown endpoint: %s", r)
	}
	if r := e.Do("POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("another organization's endpoint: %s", r)
	}
}

