func TestRotatedSecretSurvivesReload(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "Europe/Berlin", 1900, now)
	rotated := now.Add(-time.Hour)
	ep, err := st.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: o.ID, URL: "https://hooks.example/tally", Events: []string{"*"}, Secret: "whsec_new", PreviousSecret: "whsec_old", SecretRotatedAt: rotated, Enabled: true}, now)
	if err != nil {
		t.Fatal(err)
	}

	path := filepath.Join(t.TempDir(), "tally.json")
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	ep2, ok := got.WebhookEndpoint(o.ID, ep.ID)
	if !ok || ep2.Secret != "whsec_new" || ep2.PreviousSecret != "whsec_old" || !ep2.SecretRotatedAt.Equal(rotated) {
		t.Fatalf("endpoint after reload = %+v", ep2)
	}
	if !reflect.DeepEqual(got.Export(), st.Export()) {
		t.Fatal("the loaded store differs from the saved one")
	}
}

